function parseJsonSafe(value, fallback) {
  if (!value) return fallback;
  if (Array.isArray(value) || typeof value === 'object') return value;

  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

const rawResponse = $input.first()?.json?.data ?? $input.first()?.json ?? [];
const chunks = parseJsonSafe(rawResponse, []);

const contextoIa = $('Obter contexto IA').first().json || {};
const resolucaoBusca = $('Normalizar resolucao de busca').first().json || {};
const sessaoToken = $('Iniciar sessao').first().json.data || null;

const total_tokens_contextoIA = Number(resolucaoBusca.total_tokens_resolucao_busca || 0);
let total_tokens_embeddings = 0;
try {
  total_tokens_embeddings = Number($('Gerar embedding OpenRouter do chunk').first().json.usage?.total_tokens || 0);
} catch {}
const total_tokens = total_tokens_contextoIA + total_tokens_embeddings;

const metadata = {
  _rag_contextual: true,
  sessao_token: sessaoToken,
  contexto_ia: contextoIa,
  resolucao_busca: resolucaoBusca,
  pergunta_busca: resolucaoBusca.pergunta_busca || $('When Executed by Another Workflow').first().json.pergunta || '',
  pergunta_original: resolucaoBusca.pergunta_original || $('When Executed by Another Workflow').first().json.pergunta || '',
  consultar_base_conhecimento: Boolean(resolucaoBusca.consultar_base_conhecimento),
  tipo_intencao: resolucaoBusca.tipo_intencao || null,
  metodo_busca: resolucaoBusca.metodo_busca || null,
  identificadores_fortes: Array.isArray(resolucaoBusca.identificadores_fortes) ? resolucaoBusca.identificadores_fortes : [],
  documentos_apresentados: Array.isArray(resolucaoBusca.documentos_apresentados) ? resolucaoBusca.documentos_apresentados : [],
  documentos_rejeitados: Array.isArray(resolucaoBusca.documentos_rejeitados) ? resolucaoBusca.documentos_rejeitados : [],
  usar_documento_ativo: Boolean(resolucaoBusca.usar_documento_ativo),
  documento_ativo_id: resolucaoBusca.documento_ativo_id || null,
  documento_ativo_titulo: resolucaoBusca.documento_ativo_titulo || null,
  precisa_clarificacao: Boolean(resolucaoBusca.precisa_clarificacao),
  pergunta_clarificacao: resolucaoBusca.pergunta_clarificacao || null,
  assunto_ativo: resolucaoBusca.assunto_ativo || null,
  entidades_ativas: resolucaoBusca.entidades_ativas || {},
  total_tokens_contexto_busca: total_tokens,
  debug_busca_chunks: {
    metodo_busca: resolucaoBusca.metodo_busca || null,
    usou_embedding: total_tokens_embeddings > 0,
    total_tokens_resolucao_busca: total_tokens_contextoIA,
    total_tokens_embeddings
  }
};

if (!Array.isArray(chunks) || chunks.length === 0) {
  return [
    {
      json: {
        _tipo: 'sem_chunks',
        conteudo: null,
        ...metadata
      }
    }
  ];
}

return chunks.map(item => ({
  json: {
    ...item,
    ...metadata
  }
}));

function parseJsonSafe(value, fallback) {
  if (!value) return fallback;
  if (Array.isArray(value) || typeof value === 'object') return value;
  try { return JSON.parse(value); } catch { return fallback; }
}

const clean = (value) => String(value || '').trim();
const compact = (value, limit = 300) => clean(value).replace(/\s+/g, ' ').slice(0, limit);
const entrada = $('When Executed by Another Workflow').first().json || {};
const perguntaAtual = compact(entrada.pergunta, 500);
const contextoAtivo = $input.first().json || {};
const entidadesAtivas = contextoAtivo.entidades_ativas && typeof contextoAtivo.entidades_ativas === 'object'
  ? contextoAtivo.entidades_ativas
  : {};
const estadoBusca = entidadesAtivas.busca_empresarios && typeof entidadesAtivas.busca_empresarios === 'object'
  ? entidadesAtivas.busca_empresarios
  : null;

const resultados = Array.isArray(estadoBusca?.resultados) ? estadoBusca.resultados : [];
const limiteApresentados = Math.max(0, Number(estadoBusca?.exibidos || resultados.length || 0));
const empresasApresentadas = resultados.slice(0, limiteApresentados || resultados.length).map((item) => ({
  empresa_id: item.empresa_id || null,
  empresa: compact(item.empresa, 120),
  servico_id: item.servico_id || null,
  servico: compact(item.servico, 120)
}));
const totalResultados = Number(estadoBusca?.total || resultados.length || 0);
const totalExibidos = Number(estadoBusca?.exibidos || 0);
const totalRestantes = Math.max(0, totalResultados - totalExibidos);
const estadoCompacto = estadoBusca ? {
  pendente: Boolean(estadoBusca.pendente),
  consulta: compact(estadoBusca.consulta || estadoBusca.termo_inicial || ''),
  total: totalResultados,
  exibidos: totalExibidos,
  restantes: totalRestantes,
  ha_resultados_nao_exibidos: totalRestantes > 0,
  empresa_ativa_id: estadoBusca.empresa_ativa_id || null,
  empresas_apresentadas: empresasApresentadas
} : null;

const historico = parseJsonSafe(entrada.historico_recente || '[]', [])
  .map((item) => item.json || item)
  .filter((item) => item && clean(item.mensagem))
  .slice(-4)
  .map((item) => ({
    papel: clean(item.remetente_wa_user_id) === clean(entrada.wa_user_id) ? 'usuario' : 'assistente',
    mensagem: compact(item.mensagem, 400)
  }));

const entidadesSchema = {
  type: 'object', additionalProperties: false,
  properties: {
    profissao: { type: 'string' }, categoria: { type: 'string' }, servico: { type: 'string' },
    problema: { type: 'string' }, empresa: { type: 'string' }, produto: { type: 'string' },
    escopo_referencia: { type: 'string', enum: ['nenhum','empresa_unica','empresas_apresentadas'] },
    tipo_contato: { type: 'string', enum: ['nenhum','instagram','linkedin','facebook','youtube','tiktok','site','telefone','whatsapp','email','redes_sociais','todos'] }
  },
  required: ['profissao','categoria','servico','problema','empresa','produto','escopo_referencia','tipo_contato']
};
const schema = {
  type: 'object', additionalProperties: false,
  properties: {
    tipo_intencao: { type: 'string', enum: ['historico','institucional','busca_servico','mostrar_mais_empresarios','detalhe_empresa','consulta_contato','cadastro','atendimento_humano','fora_escopo','clarificacao'] },
    dominio_busca: { type: 'string', enum: ['nenhum','institucional','empresarios'] },
    modo_contexto: { type: 'string', enum: ['nova_busca','continuar_busca','sem_busca'] },
    consultar_base_conhecimento: { type: 'boolean' },
    metodo_busca: { type: 'string', enum: ['nenhum','vetorial','lexical','hibrido'] },
    pergunta_busca: { type: 'string' }, necessidade: { type: 'string' }, resposta_espera: { type: 'string' },
    precisa_clarificacao: { type: 'boolean' }, pergunta_clarificacao: { type: 'string' }, categoria_servico: { type: 'string' },
    assunto_ativo: { type: 'string' }, entidades_ativas: entidadesSchema,
    identificadores_fortes: { type: 'array', items: { type: 'string' } },
    usar_documento_ativo: { type: 'boolean' }, motivo: { type: 'string' }
  },
  required: ['tipo_intencao','dominio_busca','modo_contexto','consultar_base_conhecimento','metodo_busca','pergunta_busca','necessidade','resposta_espera','precisa_clarificacao','pergunta_clarificacao','categoria_servico','assunto_ativo','entidades_ativas','identificadores_fortes','usar_documento_ativo','motivo']
};

const body = {
  model: 'google/gemini-2.5-flash', temperature: 0, max_tokens: 650, reasoning: { enabled: false },
  response_format: { type: 'json_schema', json_schema: { name: 'elo_triagem_conversacional', strict: true, schema } },
  messages: [
    { role: 'system', content: [
      'Você faz a triagem conversacional da Elo Connect e não responde diretamente ao usuário.',
      'Interprete linguagem natural, abreviações, erros de digitação, pronomes e referências no singular ou plural usando o contexto recebido.',
      'Não dependa de palavras exatas. Exemplos: insta significa Instagram; eles, deles, algum deles e nenhum deles podem se referir às empresas apresentadas.',
      'Use consulta_contato quando o usuário perguntar por telefone, e-mail, WhatsApp, site, link ou rede social de uma ou várias empresas apresentadas.',
      'Em consulta_contato, normalize tipo_contato e indique escopo_referencia. Use empresas_apresentadas para referências coletivas.',
      'Use detalhe_empresa quando o usuário pedir explicações, funcionamento ou dados de uma empresa já apresentada. Não confunda aceitação da oferta de próximo resultado com pedido de detalhe.',
      'Use mostrar_mais_empresarios quando houver resultados não exibidos e o usuário aceitar a oferta de vê-los, inclusive com frases naturais ou pronomes como "me mostra ela", "pode mostrar", "quero ver", "mostra a próxima" ou equivalentes. Nesse caso, ela/a próxima se refere ao resultado ainda não exibido, não a uma empresa já apresentada.',
      'Em uma nova busca, use clarificacao quando a mensagem trouxer apenas uma profissão, categoria ou atividade ampla com necessidades materialmente diferentes e não informar problema, aplicação ou resultado desejado.',
      'A pergunta de clarificação deve ser uma única pergunta curta, específica para a ambiguidade percebida e oferecer alternativas naturais quando ajudarem. Exemplos de comportamento: automação pode exigir distinguir processos internos de automação industrial; eletricista pode exigir saber qual instalação ou problema elétrico precisa resolver.',
      'Não clarifique quando o usuário já descreveu um problema ou resultado concreto, mesmo que não use o nome técnico do serviço.',
      'Nunca peça novamente o serviço quando a mensagem for um follow-up claro sobre empresas já apresentadas.',
      'Uma solicitação independente de outro serviço inicia nova_busca. Uma resposta à pergunta de clarificação continua_busca.',
      'Toda a operação é de Blumenau/SC; não pergunte nem use localização.',
      'Não invente empresas, categorias, documentos, contatos ou dados.'
    ].join('\n') },
    { role: 'user', content: JSON.stringify({
      mensagem_atual: perguntaAtual,
      contexto_ativo: {
        assunto_ativo: compact(contextoAtivo.assunto_ativo || ''),
        tipo_intencao_anterior: entidadesAtivas.tipo_intencao || null,
        busca_empresarios: estadoCompacto,
        ultima_resposta_assistente: compact(contextoAtivo.ultima_resposta || '', 500)
      },
      historico
    }) }
  ]
};

return [{ json: {
  pergunta_atual: perguntaAtual,
  contexto_ativo: contextoAtivo,
  mensagens_recentes: historico,
  usar_triagem_ia: true,
  resolucao_deterministica: null,
  body_resolucao_busca: body
} }];

const clean = (value) => String(value || '').trim();
const parse = (value, fallback = null) => {
  if (!value) return fallback;
  if (typeof value === 'object') return value;
  const text = String(value).trim();
  try { return JSON.parse(text); } catch {}
  const match = text.match(/\{[\s\S]*\}/);
  if (match) { try { return JSON.parse(match[0]); } catch {} }
  return fallback;
};
const normalizarConsulta = (value, fallback) => {
  const texto = clean(value).replace(/\s+/g, ' ');
  return texto && texto.length <= 300 ? texto : clean(fallback);
};
const compactarEntidades = (value) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  return Object.fromEntries(Object.entries(value).filter(([, item]) => clean(item)));
};

const payload = $('Montar payload resolucao de busca').first().json || {};
const contexto = payload.contexto_ativo || {};
const entidadesContexto = contexto.entidades_ativas && typeof contexto.entidades_ativas === 'object'
  ? contexto.entidades_ativas
  : {};
const content = $json.choices?.[0]?.message?.content || '';
const finishReason = clean($json.choices?.[0]?.finish_reason).toLowerCase();
const nativeFinishReason = clean($json.choices?.[0]?.native_finish_reason).toUpperCase();
const respostaTruncada = finishReason === 'length' || nativeFinishReason === 'MAX_TOKENS';
const parsed = respostaTruncada ? {} : (parse(content, {}) || {});
const usage = $json.usage || {};
const permitidos = ['historico','institucional','busca_servico','mostrar_mais_empresarios','detalhe_empresa','consulta_contato','cadastro','atendimento_humano','fora_escopo','clarificacao'];
const dominios = ['nenhum','institucional','empresarios'];
const modos = ['nova_busca','continuar_busca','sem_busca'];
const metodos = ['nenhum','vetorial','lexical','hibrido'];
const pergunta = clean(payload.pergunta_atual);

let tipo = clean(parsed.tipo_intencao).toLowerCase();
if (!permitidos.includes(tipo)) tipo = 'clarificacao';
let dominio = clean(parsed.dominio_busca).toLowerCase();
if (!dominios.includes(dominio)) {
  dominio = ['busca_servico','mostrar_mais_empresarios','detalhe_empresa','consulta_contato'].includes(tipo)
    ? 'empresarios'
    : (tipo === 'institucional' ? 'institucional' : 'nenhum');
}
let modoContexto = clean(parsed.modo_contexto).toLowerCase();
if (!modos.includes(modoContexto)) {
  modoContexto = tipo === 'busca_servico' ? 'nova_busca'
    : (['mostrar_mais_empresarios','detalhe_empresa','consulta_contato'].includes(tipo) ? 'continuar_busca' : 'sem_busca');
}
if (['mostrar_mais_empresarios','detalhe_empresa','consulta_contato'].includes(tipo)) {
  dominio = 'empresarios';
  modoContexto = 'continuar_busca';
}

const entidadesBase = { ...entidadesContexto };
if (modoContexto === 'nova_busca') delete entidadesBase.busca_empresarios;
const entidadesAtivas = {
  ...entidadesBase,
  ...compactarEntidades(parsed.entidades_ativas),
  tipo_intencao: tipo,
  dominio_busca: dominio
};
const consultar = dominio === 'institucional'
  || (dominio === 'empresarios' && ['busca_servico','mostrar_mais_empresarios','detalhe_empresa','consulta_contato'].includes(tipo));
let metodo = clean(parsed.metodo_busca).toLowerCase();
if (!metodos.includes(metodo)) metodo = dominio === 'institucional' ? 'vetorial' : (dominio === 'empresarios' ? 'hibrido' : 'nenhum');
const precisaClarificacao = tipo === 'clarificacao' || Boolean(parsed.precisa_clarificacao);
const triagemValida = !respostaTruncada && permitidos.includes(clean(parsed.tipo_intencao).toLowerCase());

return [{ json: {
  pergunta_original: pergunta,
  pergunta_busca: normalizarConsulta(parsed.pergunta_busca, pergunta),
  consulta_semantica: normalizarConsulta(parsed.pergunta_busca, pergunta),
  necessidade: normalizarConsulta(parsed.necessidade, '') || null,
  resposta_espera: clean(parsed.resposta_espera) || null,
  tipo_intencao: tipo,
  dominio_busca: dominio,
  modo_contexto: modoContexto,
  consultar_base_conhecimento: consultar,
  metodo_busca: consultar ? metodo : 'nenhum',
  precisa_clarificacao: precisaClarificacao,
  pergunta_clarificacao: clean(parsed.pergunta_clarificacao) || (precisaClarificacao ? 'Pode me dar mais um detalhe para eu entender corretamente?' : null),
  categoria_servico: clean(parsed.categoria_servico) || null,
  assunto_ativo: clean(parsed.assunto_ativo) || contexto.assunto_ativo || null,
  entidades_ativas: entidadesAtivas,
  identificadores_fortes: Array.isArray(parsed.identificadores_fortes) ? parsed.identificadores_fortes.map(clean).filter(Boolean).slice(0, 10) : [],
  usar_documento_ativo: Boolean(parsed.usar_documento_ativo),
  documento_ativo_id: contexto.documento_ativo_id || null,
  documento_ativo_titulo: contexto.documento_ativo_titulo || null,
  total_tokens_resolucao_busca: Number(usage.total_tokens || 0),
  debug_resolucao_busca: {
    triagem_valida: triagemValida,
    resposta_truncada: respostaTruncada,
    motivo: clean(parsed.motivo) || (triagemValida ? 'triagem_ia' : 'fallback_triagem_invalida')
  }
} }];

